  reviewVotes        shopping_mall_review_votes[]
  reviewReports      shopping_mall_review_reports[]
  refundRequests     shopping_mall_refund_requests[]

  @@unique([email])
  @@index([created_at])
  @@index([updated_at])
  @@index([deleted_at])
}

/// JWT session tokens for customer authentication with access and refresh
