        },
      );
    typia.assert(result6);
    TestValidator.equals(
      "pagination has consistent records",
      result6.data.length <= 5,
      true,
    );
    TestValidator.equals(
      "pagination has current page",
      result6.pagination.current > 1,
      true,
    );
  }
}

