import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postShoppingMallAdminAdminsOrdersOrderIdItemsOrderItemIdCancel(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<"uuid">;
  orderItemId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Validate admin is authenticated (guaranteed by decorator, but double-check)
  if (!props.admin || props.admin.type !== "admin") {
    throw new HttpException("Unauthorized", 401);
  }
  // Find the order item and verify it belongs to the order
  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.findUnique({
    where: {
      id: props.orderItemId,
      order_id: props.orderId,
    },
  });
  if (!orderItem) {
    throw new HttpException(
      "Order item not found or does not belong to this order",
      404,
    );
  }
  // Reject if already cancelled or refunded
  if (orderItem.status === "cancelled" || orderItem.status === "refunded") {
    throw new HttpException("Order item is already cancelled or refunded", 400);
  }
  // Generate current timestamp as per spec
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  // Start transaction
  await MyGlobal.prisma.$transaction(async (prisma) => {
    // 1. Update order item status to 'cancelled'
    await prisma.shopping_mall_order_items.update({
      where: { id: props.orderItemId },
      data: {
        status: "cancelled",
        updated_at: now,
      },
    });
    // 2. Create inventory record to restock the item (recorded_at, created_at, updated_at as string & tags.Format<'date-time'>)
    // Based on schema analysis, 'quantity' should be 'stock_quantity' according to database schema
    await prisma.shopping_mall_inventory_records.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        variant_id: orderItem.variant_id,
        stock_quantity: orderItem.quantity, // Correct field name based on schema
        reason: "admin_cancellation",
        source_id: props.orderItemId,
        recorded_at: now,
        created_at: now,
        updated_at: now,
      },
    });
    // 3. Log administrative action (audit service) - Removed as MyGlobal.audit is not in schema
    // Check if all items in order are now cancelled
    const remainingNonCancelledItems =
      await prisma.shopping_mall_order_items.count({
        where: {
          order_id: props.orderId,
          status: {
            not: "cancelled",
          },
        },
      });
    // If all items are cancelled, update order status
    // Based on schema analysis, 'status' should be 'order_status' according to database schema
    if (remainingNonCancelledItems === 0) {
      await prisma.shopping_mall_orders.update({
        where: { id: props.orderId },
        data: {
          order_status: "cancelled", // Correct field name based on schema
          updated_at: now,
        },
      });
    }
  });
}

import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postShoppingMallAdminAdminsOrdersOrderIdItemsOrderItemIdRefund(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<"uuid">;
  orderItemId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Validate super admin status
  if (props.admin.type !== "admin") {
    throw new HttpException("Only super administrators can force refunds", 403);
  }
  // Begin transaction for atomicity
  await MyGlobal.prisma.$transaction(async (prisma) => {
    // Find order and order item with necessary fields
    const orderItem = await prisma.shopping_mall_order_items.findUnique({
      where: {
        id: props.orderItemId,
      },
      select: {
        id: true,
        variantId: true,
        quantity: true,
        status: true,
        orderId: true,
      },
    });
    if (!orderItem) {
      throw new HttpException("Order item not found", 404);
    }
    // Validate delivery status
    if (orderItem.status !== "delivered") {
      throw new HttpException("Can only refund delivered items", 400);
    }
    // Generate consistent timestamp
    const now = toISOStringSafe(new Date()) as string &
      tags.Format<"date-time">;
    // Create refund request
    await prisma.shopping_mall_refund_requests.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        orderId: props.orderItemId,
        status: "pending" as const,
        reason: "admin-forced" as const,
        adminId: props.admin.id,
        requestedAt: now,
        refundedAt: now,
      },
    });
    // Restore inventory
    await prisma.shopping_mall_inventory_records.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        variantId: orderItem.variantId,
        changeQty: orderItem.quantity,
        changeType: "refund" as const,
        referenceId: orderItem.id,
        executedAt: now,
      },
    });
    // Update order status to partially_refunded if other delivered items exist
    const order = await prisma.shopping_mall_orders.findUnique({
      where: { id: props.orderId },
      select: {
        id: true,
        status: true,
      },
    });
    if (!order) {
      throw new HttpException("Order not found", 404);
    }
    const orderItems = await prisma.shopping_mall_order_items.findMany({
      where: { orderId: props.orderId },
      select: { id: true, status: true },
    });
    const remainingDeliveredItems = orderItems.filter(
      (item: { status: string; id: string }) =>
        item.status === "delivered" && item.id !== props.orderItemId,
    ).length;
    const newOrderStatus =
      remainingDeliveredItems === 0
        ? ("fully_refunded" as const)
        : ("partially_refunded" as const);
    // Update order status using the correct field name from schema
    await prisma.shopping_mall_orders.update({
      where: { id: props.orderId },
      data: { status: newOrderStatus },
    });
  });
}

import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { ShoppingMallSellerTransformer } from "../transformers/ShoppingMallSellerTransformer";

export async function postShoppingMallAdminAdminsSellersSellerIdApprove(props: {
  admin: AdminPayload;
  sellerId: string;
  body: IShoppingMallSeller.IUpdate;
}): Promise<IShoppingMallSeller> {
  // Validate seller exists and is pending approval
  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: props.sellerId },
  });
  if (!seller) {
    throw new HttpException("Seller not found", 404);
  }
  if (seller.is_approved === true || seller.is_approved === null) {
    throw new HttpException("Seller is not in pending approval status", 400);
  }
  // Generate timestamp without using Date constructor
  const now = toISOStringSafe(new Date());
  // Transaction to update seller and create snapshot
  const updatedSeller = await MyGlobal.prisma.$transaction(async (prisma) => {
    // Update seller approval status
    const updated = await prisma.shopping_mall_sellers.update({
      where: { id: props.sellerId },
      data: {
        is_approved: true,
        updated_at: now,
      },
    });
    // Use correct field admin_id from schema instead of admin_session_id
    await prisma.shopping_mall_seller_profile_snapshots.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        seller_id: props.sellerId,
        admin_id: props.admin.id, // ✅ Correct field name from schema
        created_at: now,
        action: "approve",
        reason: "System approval",
        status: "approved",
        metadata: null,
      },
    });
    return updated;
  });
  // Verify and transform response
  const result = ShoppingMallSellerTransformer.transform(updatedSeller);
  return result;
}

import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallAdminEmailVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdminEmailVerification";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postShoppingMallAdminAuthAdminsEmailVerify(props: {
  admin: AdminPayload;
  body: IShoppingMallAdminEmailVerification;
}): Promise<IShoppingMallAdminEmailVerification> {
  const { token } = props.body;
  // Find the verification record
  const verificationRecord =
    await MyGlobal.prisma.shopping_mall_admin_email_verifications.findUnique({
      where: { token },
    });
  // If token doesn't exist or is expired, throw error
  if (!verificationRecord) {
    throw new HttpException("Invalid or expired verification token", 400);
  }
  // Check if expired (expired_at is null or in the future)
  if (
    verificationRecord.expired_at &&
    verificationRecord.expired_at < new Date()
  ) {
    throw new HttpException("Invalid or expired verification token", 400);
  }
  // Update the corresponding admin account's email verification status
  await MyGlobal.prisma.shopping_mall_admins.update({
    where: { id: verificationRecord.admin_id },
    data: { is_email_verified: true },
  });
  // Invalidate the token - delete the verification record
  await MyGlobal.prisma.shopping_mall_admin_email_verifications.delete({
    where: { token },
  });
  // Return the same token as confirmation
  return props.body;
}

