    );
  }
  await MyGlobal.prisma.shopping_mall_sellers.update({
    where: { id: props.seller.id },
    data: { email_verified: true },
  });
  await MyGlobal.prisma.shopping_mall_seller_email_verifications.delete({
    where: { id: verification.id },
  });
}

