}): Promise<void> {
  // Find seller to ban
  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: props.sellerId },
  });
  // If seller doesn't exist or is already suspended, return 204 (idempotent)
