  const viewCountResult =
    await MyGlobal.prisma.shopping_mall_sale_view_stats.aggregate({
      where: {
        created_at: {
          gte: currentMonthStart,
          lte: currentMonthEnd,
        },
      },
      _count: {
        id: true,
      },
    });
  const purchaseCount = purchaseCountResult._count?.id ?? 0;
  const viewCount = viewCountResult._count?.id ?? 0;
  // Avoid division by zero
  const conversionRate = viewCount > 0 ? purchaseCount / viewCount : 0;
  // Calculate customer retention rate: repeat customers / total customers
  const customerPurchaseCounts =
    await MyGlobal.prisma.shopping_mall_orders.groupBy({
      by: ["customer_id"],
      where: {
        created_at: {
          gte: currentMonthStart,
          lte: currentMonthEnd,
        },
        payment_status: "2", // Changed from number to string
      },
      _count: {
        id: true,
      },
    });
  const totalCustomers = customerPurchaseCounts.length;
  const repeatCustomers = customerPurchaseCounts.filter(
    (customer) => customer._count?.id > 1,
  ).length;
  // Avoid division by zero
  const customerRetentionRate =
    totalCustomers > 0 ? repeatCustomers / totalCustomers : 0;
  // Get top 10 performing products by sales volume (quantity * unit_price)
  // Product aggregation with total sales volume per product
  const topProductsResult =
    await MyGlobal.prisma.shopping_mall_order_items.findMany({
      where: {
        order: {
          created_at: {
            gte: currentMonthStart,
            lte: currentMonthEnd,
          },
          payment_status: "2", // Changed from number to string
        },
      },
      include: {
        product: true,
      },
      take: 10,
      orderBy: {
        price_at_time: "desc",
      },
    });
  const topProducts = topProductsResult.map((item) => ({
    id: item.product_id,
  }));
  // Get bottom 10 performing products by sales volume
  const bottomProductsResult =
    await MyGlobal.prisma.shopping_mall_order_items.findMany({
      where: {
        order: {
          created_at: {
            gte: currentMonthStart,
            lte: currentMonthEnd,
          },
          payment_status: "2", // Changed from number to string
        },
      },
      include: {
        product: true,
      },
      take: 10,
      orderBy: {
        price_at_time: "asc",
      },
    });
  const bottomProducts = bottomProductsResult.map((item) => ({
    id: item.product_id,
  }));
  // Return complete sales metrics
  return {
    totalSales,
    averageOrderValue,
    inventoryTurnoverRate,
    conversionRate,
    customerRetentionRate,
    topProducts,
    bottomProducts,
  };
}

import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postShoppingMallAdminOrdersOrderIdItemsOrderItemIdRefund(props: {
  admin: AdminPayload;
  orderId: string;
  orderItemId: string;
  body: IShoppingMallRefundRequest;
}): Promise<IShoppingMallRefundRequest> {
  // Validate order item exists and is delivered
  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.findUnique({
    where: { id: props.orderItemId },
  });
  if (!orderItem) {
    throw new HttpException("Order item not found", 404);
  }
  // Validate order item belongs to the specified order
  if (orderItem.order_id !== props.orderId) {
    throw new HttpException("Order item does not belong to this order", 400);
  }
  if (orderItem.status !== "delivered") {
    throw new HttpException(
      "Refund can only be requested for delivered items",
      400,
    );
  }
  // Retrieve the order to get the customer_id
  const order = await MyGlobal.prisma.shopping_mall_orders.findUnique({
    where: { id: props.orderId },
  });
  if (!order) {
    throw new HttpException("Order not found", 404);
  }
  // Create refund request in database with status 'pending'
  // Even though the API docs show status 'approved' or 'rejected', the specification says:
  // "Initial state is 'pending' when created by customer, then transitions to 'approved' or 'rejected' by seller/admin"
  // The provided IShoppingMallRefundRequest DTO is the response DTO from the admin, not the internal state
  const refundRequest =
    await MyGlobal.prisma.shopping_mall_refund_requests.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        customer_id: order.customer_id,
        order_item_id: props.orderItemId,
        reason: "No reason provided", // Removed reference to non-existent props.body.reason
        status: "pending",
        created_at: toISOStringSafe(new Date()) as string &
          tags.Format<"date-time">,
        requested_at: toISOStringSafe(new Date()) as string &
          tags.Format<"date-time">,
        updated_at: toISOStringSafe(new Date()) as string &
          tags.Format<"date-time">,
      },
    });
  // Return the response DTO as specified in IShoppingMallRefundRequest
  // This DTO is a confirmation message, not the internal refund request state
  return {
    status: props.body.status,
    message:
      props.body.status === "approved"
        ? "Refund request has been approved for processing."
        : "Refund request has been rejected.",
  };
}

import { ArrayUtil } from "@nestia/e2e";
