import { Controller, Ip } from "@nestjs/common";
import { TypedRoute, TypedBody } from "@nestia/core";
import typia from "typia";
import { postShoppingMallAuthSellerJoin } from "../../../../providers/postShoppingMallAuthSellerJoin";
import { postShoppingMallAuthSellerLogin } from "../../../../providers/postShoppingMallAuthSellerLogin";
import { postShoppingMallAuthSellerRefresh } from "../../../../providers/postShoppingMallAuthSellerRefresh";

import { IShoppingMallSeller } from "../../../../api/structures/IShoppingMallSeller";

@Controller("/shoppingMall/auth/seller")
export class ShoppingmallAuthSellerController {
  /**
   * Register a new seller account on the platform. This operation creates a new
   * seller record with initial status 'pending_verification'. The system sends
   * a verification email to the provided address, and the account remains
   * inactive until email verification is completed. The seller's password is
   * securely hashed and stored in the password_hash field of the
   * shopping_mall_sellers table. The email field must be unique across all
   * actors. After successful registration, the seller cannot log in until they
   * verify their email address through the confirmation link. This operation
   * aligns with the seller onboarding workflow defined in 03-seller-account.md
   * where registration triggers 'pending_verification' status before
   * administrative approval.
   *
   * The implementation relies on the shopping_mall_sellers table which contains
   * essential fields for seller registration: email, password_hash, and
   * created_at. The shopping_mall_seller_email_verifications table is used to
   * store temporary verification tokens with expiration times to ensure secure
   * email validation. Registration requires only email and password parameters
   * as the rest of the profile details (shop name, description, logo) are
   * completed after verification.
   *
   * This operation is critical for seller onboarding and must be publicly
   * accessible to allow any business to register. The account cannot be fully
   * activated without email verification, which prevents fake or spam
   * registrations. The system's snapshot principle ensures all registration
   * events are auditable.
   *
   * The user's email must be validated using the format restrictions specified
   * in the 03-seller-account.md document, and password must meet minimum
   * complexity requirements (min 12 characters, uppercase, lowercase, digit,
   * special character). The password is never stored in plain text.
   *
   * Related operations: The seller must complete email verification via POST
   * /auth/seller/verify-email before they can proceed to any other operations.
   *
   * @param connection
   * @param body Credentials for registering a new seller account on the
   *   platform.
   * @setHeader token.access Authorization
   *
   * @x-autobe-specification 1. Receive email and password from request body
   * 2. Validate email format and uniqueness (check in shopping_mall_sellers table)
   * 3. Validate password complexity: min 12 chars, uppercase, lowercase, digit, special char
   * 4. Hash password with bcrypt
   * 5. Create new record in shopping_mall_sellers with status 'pending_verification'
   * 6. Generate email verification token with UUID and expires_at (24 hours from now)
   * 7. Insert verification token into shopping_mall_seller_email_verifications table
   * 8. Send verification email with reset link containing token
   * 9. Generate JWT access token and refresh token for session
   * 10. Return access_token, refresh_token, seller_id, email, role, and status in response
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IShoppingMallSeller.IJoin,
  ): Promise<IShoppingMallSeller.IAuthorized> {
    try {
      return await postShoppingMallAuthSellerJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Authenticate a seller and establish a session using email and password
   * credentials. This operation validates the seller's credentials against the
   * shopping_mall_sellers table and, upon successful authentication, issues a
   * JWT access token and refresh token. The seller's status must be "approved"
   * for login to succeed. Accounts with status "pending_verification",
   * "pending_approval", or "rejected" are denied access.
   *
   * The implementation uses the password_hash field from the
   * shopping_mall_sellers table to verify the provided password against the
   * stored hash. The session management relies on the
   * shopping_mall_seller_sessions table to store the refresh token and track
   * active sessions with expiration times. This ensures secure, stateless
   * authentication while maintaining token revocation capability.
   *
   * According to 03-seller-account.md, authentication must occur for sellers
   * who have been approved by administrators. The seller's status must be
   * 'approved' before any login attempts are successful. Attempting to login
   * with 'pending_verification', 'pending_approval', or 'rejected' status will
   * return a 403 Forbidden error.
   *
   * This endpoint implements the authentication flow specified in the
   * requirements and integrates with the password_reset mechanism that allows
   * secure credential recovery. The response includes the seller's complete
   * profile information to support subsequent API calls.
   *
   * Related operations: This follows email verification (POST
   * /auth/seller/join) and administrative approval (via admin endpoint). The
   * seller must complete both steps before using this endpoint.
   *
   * @param connection
   * @param body Login credentials for authenticating a registered seller on the
   *   platform.
   * @setHeader token.access Authorization
   *
   * @x-autobe-specification 1. Receive email and password from request body
   * 2. Look up seller in shopping_mall_sellers by email
   * 3. Verify seller status is 'approved' (reject if 'pending_verification', 'pending_approval', 'rejected', or 'suspended')
   * 4. Compare provided password with stored password_hash using bcrypt comparison
   * 5. If password match: generate JWT access token (expiration: 30m) and refresh token (expiration: 7d)
   * 6. Store refresh token with seller_id and expiration in shopping_mall_seller_sessions table
   * 7. Return access_token, refresh_token, seller_id, email, role, status, shop_name, shop_description, logo_url, created_at, updated_at in response
   * 8. If password mismatch or seller not found: return 401 Unauthorized
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IShoppingMallSeller.ILogin,
  ): Promise<IShoppingMallSeller.IAuthorized> {
    try {
      return await postShoppingMallAuthSellerLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Renew an expired access token by using a valid refresh token without
   * requiring re-authentication with email and password. This operation
   * validates the refresh token against the shopping_mall_seller_sessions table
   * to ensure it exists, has not expired, and is associated with an approved
   * seller account.
   *
   * The system uses the refresh token stored in the
   * shopping_mall_seller_sessions table to verify authenticity and validity of
   * the token. Upon successful validation, new access and refresh tokens are
   * issued, invalidating the old refresh token for security purposes. This
   * follows the token rotation security pattern.
   *
   * The refresh token has a 7-day expiration period as specified in the
   * authentication strategy. This allows sellers to maintain authenticated
   * sessions for extended periods without frequent re-login, while still
   * ensuring security through token rotation. All refresh token operations are
   * audited in the session tracking table.
   *
   * This operation can only be used after successful login (POST
   * /auth/seller/login) following account approval. The seller must have an
   * active, approved account status to use this refresh mechanism.
   *
   * Related operations: This follows POST /auth/seller/login. The refresh token
   * obtained during login is required as input to this operation.
   *
   * @param connection
   * @param body Refresh token for obtaining a new access token without
   *   requiring full re-authentication.
   * @setHeader token.access Authorization
   *
   * @x-autobe-specification 1. Receive refresh_token from request body
   * 2. Look up session record in shopping_mall_seller_sessions by refresh_token
   * 3. Verify session exists and has not expired
   * 4. Verify associated seller account status is 'approved'
   * 5. Generate new JWT access token (expiration: 30m) and new refresh token (expiration: 7d)
   * 6. Remove old refresh token from shopping_mall_seller_sessions table
   * 7. Insert new refresh token into shopping_mall_seller_sessions with new expiration
   * 8. Return new access_token, new refresh_token, seller_id, email, role, status, shop_name, shop_description, logo_url, created_at, updated_at in response
   * 9. If token invalid, expired, or associated seller is not approved: return 401 Unauthorized
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IShoppingMallSeller.IRefresh,
  ): Promise<IShoppingMallSeller.IAuthorized> {
    try {
      return await postShoppingMallAuthSellerRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

