import { Controller, Ip } from "@nestjs/common";
import { TypedRoute, TypedBody } from "@nestia/core";
import typia from "typia";
import { postShoppingMallAuthAdminJoin } from "../../../../providers/postShoppingMallAuthAdminJoin";
import { postShoppingMallAuthAdminRefresh } from "../../../../providers/postShoppingMallAuthAdminRefresh";

import { IShoppingMallAdmin } from "../../../../api/structures/IShoppingMallAdmin";

@Controller("/shoppingMall/auth/admin")
export class ShoppingmallAuthAdminController {
  /**
   * This operation allows a super administrator to manually create a new
   * administrator account within the system, providing immediate access to
   * administrative controls without relying on an application process.
   *
   * This is a direct registration pathway (equivalent to 'join') that bypasses
   * standard approval workflows. The system creates an entry in the
   * shopping_mall_admins table with admin_email, admin_password_hash,
   * admin_role='admin', and admin_is_active=true.
   *
   * Key database schema fields: admin_email, admin_password_hash, admin_role,
   * admin_created_at, admin_updated_at. The admin_password_hash is generated
   * using bcrypt from the password provided in the request body. The
   * admin_email must be globally unique and not conflict with existing customer
   * or seller emails.
   *
   * This operation is exclusively for super administrators. The system ensures
   * the created admin receives an initial JWT access token and refresh token
   * for login. A session record is created in shopping_mall_admin_sessions.
   *
   * This operation does not trigger referral notifications or onboarding emails
   * — those are handled explicitly by the user who invokes it.
   *
   * This operation is available only to super administrators. Access is
   * strictly controlled via the authorizationActor: superAdmin.
   *
   * @param connection
   * @param body Credentials to create the new admin account including email and
   *   password.
   * @setHeader token.access Authorization
   *
   * @x-autobe-specification Service layer validates JWT and extracts admin context. Ensures admin is authenticated. Creates a new admin account for a user with role 'admin' if user is not already a customer or seller. Validates admin_email (unique), admin_password_hash, and active status. Returns 201 with new admin ID and initial session token.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IShoppingMallAdmin.IJoin,
  ): Promise<IShoppingMallAdmin.IAuthorized> {
    try {
      return await postShoppingMallAuthAdminJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * This operation refreshes an administrator’s expired access token using a
   * valid, unexpired refresh token. This prevents admin users from being logged
   * out during extended administrative sessions.
   *
   * Key schema fields: refresh_token (in Authorization header),
   * admin_session_id, refresh_token_expires_at. The system checks the provided
   * refresh token against the most recent session recording in
   * shopping_mall_admin_sessions. If expired or unverified, the operation
   * returns 401.
   *
   * Upon success, a new access token (15-minute life) and a new refresh token
   * (7-day life) are generated and returned. The old refresh token is
   * invalidated and removed from the session store. The new refresh token is
   * stored as the active token.
   *
   * This operation is protected — it requires a valid refresh token to
   * function. It is designed to be called silently when the access token
   * expires, enabling seamless admin experience.
   *
   * This operation is available only to authenticated admin users holding a
   * valid refresh token. The authorizationType is defined as "refresh". It does
   * not require the JWT access token to be valid — only the refresh token.
   *
   * No prerequisites are required for this operation. Access is strictly
   * controlled via the authorizationType: "refresh".
   *
   * @param connection
   * @param body Refresh token to acquire a new access token.
   * @setHeader token.access Authorization
   *
   * @x-autobe-specification Service layer validates refresh token against storage in shopping_mall_admin_sessions. If valid and not expired, generates new access token and refresh token. Extends session lifetime. Updates session record with new token values. Returns 200 with new tokens. Returns 401 if invalid or expired refresh token.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IShoppingMallAdmin.IRefresh,
  ): Promise<IShoppingMallAdmin.IAuthorized> {
    try {
      return await postShoppingMallAuthAdminRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

