import { Controller, Ip } from "@nestjs/common";
import { TypedRoute, TypedBody } from "@nestia/core";
import typia from "typia";
import { postShoppingMallAuthSuperAdminJoin } from "../../../../providers/postShoppingMallAuthSuperAdminJoin";
import { postShoppingMallAuthSuperAdminLogin } from "../../../../providers/postShoppingMallAuthSuperAdminLogin";
import { postShoppingMallAuthSuperAdminRefresh } from "../../../../providers/postShoppingMallAuthSuperAdminRefresh";

import { IShoppingMallSuperAdmin } from "../../../../api/structures/IShoppingMallSuperAdmin";

@Controller("/shoppingMall/auth/superAdmin")
export class ShoppingmallAuthSuperadminController {
  /**
   * This API operation creates a new super administrator account for the
   * platform. The operation requires a valid email address and password to be
   * provided in the request body. The system checks for email uniqueness across
   * all actor tables (customers, sellers, admins, superAdmins) and rejects
   * registration if the email already exists. Upon successful validation, the
   * password is securely hashed using bcrypt before being stored in the
   * shopping_mall_super_admins table. The system then creates an initial email
   * verification token in the shopping_mall_super_admin_email_verifications
   * table, which will be used to verify the user's email ownership. A JWT
   * access token and refresh token are generated and returned in the
   * IShoppingMallSuperAdmin.IAuthorized response object. This token pair
   * enables the user to authenticate subsequent requests to protected
   * superAdmin endpoints. The creation of the superAdmin account does not
   * automatically grant privileges to manage other users until their account is
   * approved by existing superAdmins, though the account itself is created
   * immediately. This prevents unauthorized privilege escalation while allowing
   * administrators to register in advance of approval workflows.
   *
   * Security considerations require that this endpoint be publicly accessible
   * to allow initial superAdmin registration during platform onboarding, but
   * subsequent registrations must be restricted to prevent system compromise.
   * Password strength must be enforced using minimum length and complexity
   * rules, and the request body must contain both email and password fields.
