import { SellerPayload } from "../../../../decorators/payload/SellerPayload";

import { IShoppingMallRefundRequest } from "../../../../api/structures/IShoppingMallRefundRequest";

@Controller("/shoppingMall/seller/refund-requests/:refundRequestId")
export class ShoppingmallSellerRefund_requestsController {
  /**
   * Update the status and decision reason for a refund request, triggering
   * either approval of the refund or rejection of the request.
   *
   * This operation allows sellers to respond to customer refund requests by
   * either approving the refund, which restores inventory to the affected
   * product variant, or rejecting the request, which maintains the current
   * order fulfillment state. The refund request system operates under the
   * system's snapshot principle, where every modification to a refund request
   * state creates an immutable snapshot in the
   * shopping_mall_refund_request_snapshots table for audit trail and compliance
   * purposes.
   *
   * When a refund request is approved (action: 'approve'), the system
   * automatically restores the purchased product variant's inventory quantity
   * to the available stock. This inventory restoration is recorded as a
   * negative adjustment in the shopping_mall_inventory_records table with the
   * sourceType 'refund' and references the original order_item_id from the
   * refund request. The refund amount is processed through the payment gateway
   * for customer reimbursement.
   *
   * If the refund request is rejected (action: 'reject'), the system maintains
   * the current order state and sends notification to the customer with the
   * provided rejection reason. The rejection reason must clearly explain why
   * the refund request was denied, such as 'item received in good condition' or
   * 'refund request outside policy window'.
   *
   * This operation integrates with the shopping_mall_refund_requests table and
   * is protected by the seller's authorization. Only sellers who processed the
   * original order item can respond to the refund request. No other actors,
   * including customers or administrators, can modify these refund requests
   * through this endpoint.
   *
   * Related operations: GET /refund-requests/{refundRequestId} for viewing
   * refund request details, DELETE /refund-requests/{refundRequestId} for
   * cancellation of refund request before seller response, and GET
   * /refund-requests?orderItemId={id} for listing all refund requests related
   * to a specific order item.
   *
   * The response body contains the updated refund request entity with its new
   * status, rejection reason (if applicable), and timestamps for the decision.
   * The operation follows the complete snapshot principle where both the before
   * and after states of the refund request are preserved in the
   * shopping_mall_refund_request_snapshots table, ensuring full audit
   * compliance and traceability of refund decision-making throughout the
   * system.
   *
   * @param connection
   * @param refundRequestId Unique identifier for the refund request to be
   *   updated
   * @param body Decision and reason for updating the refund request status
   * @x-autobe-specification Query the shopping_mall_refund_requests table to retrieve the refund request record using the refundRequestId path parameter. Validate that the seller making the request is the same seller who processed the original order item (using seller_id from refund_request and seller_id from order_item). If the seller is not authorized, return 403 Forbidden. If the refund request is already closed (status: 'approved' or 'rejected'), return 409 Conflict. For action: 'approve': 1. Update the refund request status to 'approved' and record the decision timestamp and responder. 2. Add the refunded quantity back to the product variant's stock in the shopping_mall_inventory_records table with sourceType: 'refund' and reference the order_item_id. 3. Create an immutable snapshot of the refund request state in shopping_mall_refund_request_snapshots. 4. Trigger payment gateway refund processing. For action: 'reject': 1. Update the refund request status to 'rejected' and record the decision timestamp and responder's reason. 2. Create an immutable snapshot of the refund request state in shopping_mall_refund_request_snapshots. 3. Notify customer via email/SMS of the rejection. All database updates must occur within a single transaction to ensure data consistency. Return the updated refund request entity as response.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put()
  public async update(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("refundRequestId")
    refundRequestId: string,
    @TypedBody()
    body: IShoppingMallRefundRequest.IUpdate,
  ): Promise<IShoppingMallRefundRequest> {
    try {
      return await putShoppingMallSellerRefundRequestsRefundRequestId({
        seller,
        refundRequestId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

