@Controller("/shoppingMall/products/search")
export class ShoppingmallProductsSearchController {
  /**
   * Retrieve a paginated list of products matching search criteria with
   * advanced filtering and sorting. This operation operates on the
   * shopping_mall_products table and supports multi-dimensional search across
   * product name, category, price range, and stock availability. Search term
   * performs case-insensitive partial match on product name across all products
   * regardless of seller status or deletion flag.
   *
   * Security considerations require authenticted customer access only.
   * Unauthenticated users are not permitted to access the search endpoint.
   * Search results respect product visibility rules: only show active products
   * with at least one active variant and from approved (not suspended)
   * sellers.
   *
   * When filtering by category, the system includes products in the selected
   * category and all associated subcategories. Price range filtering uses the
   * minimum variant price for products with multiple variants, or base price
   * for products with single variants. The inStockOnly filter excludes products
   * where all variants have zero or negative stock, ensuring only available
   * products are returned. Sorting supports three modes: newest first (by
   * creation timestamp), price low to high (by minimum variant price), and
   * price high to low (by maximum variant price). Results are returned with
   * pagination parameters including total count and current page information.
   *
   * This operation integrates with the Product Service to ensure real-time
   * accuracy of product data, including current inventory levels and seller
   * status. It does not return product details or variants directly but
   * provides summarized information for display in listings. Product details
   * can be retrieved individually via GET /products/{productId} endpoint.
   *
   * @param connection
   * @param body Search criteria and pagination parameters for product filtering
   *   including search term, category, price range, in-stock only flag, and
   *   sorting preference.
   * @x-autobe-specification Query shopping_mall_products table with left joins to product variants, seller profiles, and product categories. Apply filters based on search term (ILIKE on name), category hierarchy (using category_id tree), price range (min/max variant price), and stock availability (sum of inventory records > 0). Sort results based on requested criteria: createdAt DESC for newest, min_variant_price ASC for price low to high, max_variant_price DESC for price high to low. Implement cursor-based pagination using createdAt and productId for infinite scroll support. Build response with only essential summary fields: productId, name, basePrice, categoryName, sellerName, imageUrl, averageRating, reviewCount, isAvailable, variantCount. Cache results for 5 minutes with cache key including search parameters to improve performance under load. Convert product summaries to IPageIShoppingMallProduct.ISummary type structure for response.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @TypedBody()
    body: IShoppingMallProduct.IRequest,
  ): Promise<IPageIShoppingMallProduct.ISummary> {
    try {
      return await patchShoppingMallProductsSearch({
        body,
      });
