import { Controller } from "@nestjs/common";
import { TypedRoute } from "@nestia/core";
import typia from "typia";
import { getShoppingMallSellerAnalyticsSalesMonthly } from "../../../../../../providers/getShoppingMallSellerAnalyticsSalesMonthly";
import { SellerAuth } from "../../../../../../decorators/SellerAuth";
import { SellerPayload } from "../../../../../../decorators/payload/SellerPayload";

import { IPageIShoppingMallSaleViewStat } from "../../../../../../api/structures/IPageIShoppingMallSaleViewStat";

@Controller("/shoppingMall/seller/analytics/sales/monthly")
export class ShoppingmallSellerAnalyticsSalesMonthlyController {
  /**
   * Compute monthly sales statistics by aggregating data from the
   * shopping_mall_orders and shopping_mall_order_items tables using GROUP BY
   * month.
   *
   * This operation provides a comprehensive view of sales performance over
   * time. It calculates total revenue, total order count, average order value,
   * and other key metrics for each month, enabling users to identify sales
   * trends and seasonal patterns.
   *
   * Implementation note: This does NOT map to a single database table - instead
   * it executes:
   *
   * SELECT DATE_TRUNC('month', o.created_at) as month, COUNT(*) as order_count,
   * SUM(oi.quantity * oi.price) as revenue, AVG(oi.quantity * oi.price) as
   * average_order_value, SUM(CASE WHEN o.status = 'delivered' THEN 1 ELSE 0
   * END) as delivered_order_count FROM shopping_mall_orders o JOIN
   * shopping_mall_order_items oi ON o.order_id = oi.order_id WHERE o.status IN
   * ('paid', 'shipped', 'delivered') GROUP BY DATE_TRUNC('month', o.created_at)
   * ORDER BY month DESC
   *
   * This statistical aggregation serves the business need for sales trend
   * analysis and informs inventory planning, marketing campaigns, and financial
   * forecasting.
   *
   * Security considerations: Access to this endpoint is restricted to
   * authenticated users with appropriate permissions (typically admin or
   * dashboard users). Rate limiting is applied to prevent API abuse.
   *
   * Related operations: This data can be visualized in conjunction with GET
   * /products/search for product-level sales analysis and GET
   * /sellers/me/dashboard for seller-specific performance tracking.
   *
   * @param connection
   * @x-autobe-specification Query shopping_mall_orders and shopping_mall_order_items tables using GROUP BY month to compute sales statistics. Join orders with order items to calculate revenue from quantities and prices. Filter for orders with status 'paid', 'shipped', or 'delivered'. Aggregate results to compute: order count, total revenue, average order value, and delivered order count. Implement cursor-based pagination for large result sets. Cache results for 15 minutes with cache key based on query parameters and user permissions. Apply rate limiting of 100 requests per minute per user. Return results sorted by month in descending order (newest first).
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async index(
    @SellerAuth()
    seller: SellerPayload,
  ): Promise<IPageIShoppingMallSaleViewStat> {
    try {
      return await getShoppingMallSellerAnalyticsSalesMonthly({
        seller,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

