import { Controller } from "@nestjs/common";
import { TypedRoute } from "@nestia/core";
import typia from "typia";
import { getShoppingMallSellerAnalyticsProductsEngagement } from "../../../../../../providers/getShoppingMallSellerAnalyticsProductsEngagement";
import { SellerAuth } from "../../../../../../decorators/SellerAuth";
import { SellerPayload } from "../../../../../../decorators/payload/SellerPayload";

import { IPageIShoppingMallProduct } from "../../../../../../api/structures/IPageIShoppingMallProduct";

@Controller("/shoppingMall/seller/analytics/products/engagement")
export class ShoppingmallSellerAnalyticsProductsEngagementController {
  /**
   * This endpoint computes product engagement metrics by aggregating customer
   * behavior data across the shoppingMall platform. The data is derived from
   * the shopping_mall_sales, shopping_mall_cart_items, and
   * shopping_mall_review_snapshots tables. Each product's engagement score
   * represents its popularity and customer interaction strength, enabling
   * strategic insights into product performance.
   *
   * The operation calculates the following metrics per product: total sales
   * count, total cart additions, average review rating, total review count, and
   * total revenue generated. These are grouped by product_id and product_name,
   * returning a comprehensive view of which products drive the most customer
   * activity and revenue. Data includes only active products with approved
   * sellers and excludes deleted or suspended products.
   *
   * Security and authorization: This endpoint is restricted to administrators
   * and super administrators due to the sensitivity of strategic business
   * insights. Regular customers and sellers do not have access to this level of
   * analytics. Rate limiting applies to prevent abuse of this resource-heavy
   * query. The metrics are computed in real-time without caching to ensure data
   * accuracy during reporting cycles.
   *
   * Comparison with other endpoints: Unlike GET /products which returns product
   * listings and variants, this endpoint does not return variant-level or
   * individual transaction data. It is a higher-level aggregate view that
   * complements product management features by providing data-driven insights.
   * External tools such as reporting dashboards rely on this endpoint to
   * visualize product performance trends over time. The metrics are also used
   * internally to power recommendation engines and inventory forecasting
   * models.
   *
   * Database dependencies: This operation relies on the integrity of the
   * shopping_mall_sales table for completed transactions,
   * shopping_mall_cart_items for pre-purchase interest, and
   * shopping_mall_review_snapshots for customer feedback. All product and
   * seller status fields are filtered to ensure only active and approved
   * entities contribute to the result.
   *
   * Performance optimization: The system utilizes indexed views on the
   * underlying tables to optimize aggregation performance. Aggregation joins
   * are optimized and computed with efficient GROUP BY clauses. The response
   * includes pagination to handle large datasets efficiently without
   * performance degradation.
   *
   * Error handling: If no sales or cart data exists for products, metrics
   * default to zero. The operation avoids complex nested joins and maintains a
   * flat structure for reliability. The specification ensures clarity for
   * downstream agents implementing the service layer logic.
   *
   * @param connection
   * @x-autobe-specification Query the shopping_mall_sales table to count total sales per product, sum revenue, and join with shopping_mall_cart_items to count cart additions. Join with shopping_mall_review_snapshots to calculate average rating and total reviews. Group by product_id and product_name. Filter for active products (isDeleted = false) and active sellers (approvalStatus = 'approved'). For each group, compute: sales_count = COUNT(sales.id), cart_additions = COUNT(cart_items.id), avg_rating = AVG(reviews.rating), review_count = COUNT(reviews.id), total_revenue = SUM(sales.total_amount). Use pagination with limit and offset. Do not cache results; computations are done on-the-fly for accuracy. Log query execution time for performance monitoring.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async index(
    @SellerAuth()
    seller: SellerPayload,
  ): Promise<IPageIShoppingMallProduct> {
    try {
      return await getShoppingMallSellerAnalyticsProductsEngagement({
        seller,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

