import { IShoppingMallCartItem } from "../../../../../../api/structures/IShoppingMallCartItem";

@Controller("/shoppingMall/customer/cart/me/metrics")
export class ShoppingmallCustomerCartMeMetricsController {
  /**
   * Retrieve comprehensive cart metrics for the authenticated customer.
   *
   * This endpoint provides aggregated statistics about the customer's shopping
   * cart, including total number of items, unique product variants, total cart
   * value, and availability status of items. The operation queries the
   * shopping_mall_cart_items table, which contains cart items with their
   * associated variant IDs, quantities, unit prices, and availability status.
   *
   * The cart metrics are calculated in real-time from the current cart state.
   * The service aggregates data across all cart items to provide summary
   * statistics. This operation is essential for the frontend to display cart
   * summary information to users before proceeding to checkout.
   *
   * The endpoint returns aggregated statistics only, without exposing the full
   * cart item details. The cart metrics provide a compact summary view to
   * improve UI performance.
   *
   * Related operations: GET /cart to retrieve full cart items, POST /cart to
   * add items to cart, PUT /cart/{cartId} to update cart item quantity, DELETE
   * /cart to clear cart.
   *
   * Security: This endpoint is only accessible to authenticated customers.
   * Authorization is enforced at the API gateway layer. The customer ID is
   * extracted from the JWT token and used to filter cart items.
   *
   * Performance considerations: The operation performs aggregation at the
   * database level using GROUP BY queries, avoiding retrieval of full cart item
   * records. This ensures fast response times even during high traffic
   * periods.
   *
   * @param connection
   * @x-autobe-specification Query the shopping_mall_cart_items table to calculate cart statistics.
   * - Calculate total quantity of all cart items: SUM(quantity)
   * - Calculate count of unique cart items: COUNT(DISTINCT variantId)
   * - Calculate total cart value: SUM(quantity * unit_price)
   * - Calculate number of available items: COUNT where isAvailable = true and stockQuantity > 0
   * - Calculate number of unavailable items: COUNT where isAvailable = false or stockQuantity = 0
   * - Return results as a single JSON object with all metrics
   * - Cache results for 1 minute using customer_id as cache key
   * - Apply database query indexes on customer_id, isAvailable, and stockQuantity for performance optimization
   * - Ensure query only retrieves data for the authenticated customer from JWT token
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async meMetrics(
    @CustomerAuth()
    customer: CustomerPayload,
  ): Promise<IShoppingMallCartItem> {
    try {
      return await getShoppingMallCustomerCartMeMetrics({
        customer,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

