@Controller("/shoppingMall/search/products/global")
export class ShoppingmallSearchProductsGlobalController {
  /**
   * Perform a comprehensive global search across all products, variants, and
   * sellers in the shoppingMall platform. This operation aggregates data from
   * multiple tables including shopping_mall_products, shopping_mall_sales, and
   * shopping_mall_sellers to provide a unified search experience that
   * transcends individual product listings. The system performs a full-text
   * search on product names and descriptions, matches against variant SKUs, and
   * filters results by category, price range, and availability, returning a
   * paginated summary of enriched product results.
   *
   * This is a non-CRUD operation that combines data from multiple database
   * entities into a single concatenated result set. The search includes
   * products from all approved sellers, but excludes products from suspended or
   * rejected sellers. The response includes product name, description, average
   * rating, seller name, variant options, and price range information. For
   * products with multiple variants, only the lowest and highest available
   * prices are included in the result set to provide a clear price range.
   *
   * Security considerations are strictly enforced: only products owned by
   * approved sellers are included in results. Products from suspended or
   * rejected sellers are excluded. The search results do not return any
   * protected customer data or seller contact information. Access control is
   * enforced by the authorization layer, which allows all authenticated users
   * to perform this search.
   *
   * This operation requires pagination, sorting, and advanced filtering
   * capabilities. Results are paginated with a default limit of 10 items per
   * page, supporting page sizes up to 50. Results can be sorted by relevance,
   * newest products, lowest price, or highest price. The search functionality
   * respects product availability, allowing users to filter for "in stock only"
   * products. Results return every product variant's description along with
   * product-level metadata to give users comprehensive information about each
   * listing.
   *
   * When a product has been removed by its seller, it is permanently deleted
   * from search results, but products with removed variants remain searchable
   * based on their active variants.
   *
   * Related operations: GET /products/{productId} to view detailed product
   * information, GET /categories to browse products by category, and GET
   * /sellers/me/dashboard to view seller-specific products.
   *
   * @param connection
   * @param body Search criteria and filtering parameters for the global product
   *   search operation.
   * @x-autobe-specification Search across shopping_mall_products, shopping_mall_sales, and shopping_mall_sellers tables using full-text search on product name and description, SKU code matching, and category filtering. Join products with their active variants and seller profile data. Filter based on inbound parameters: query term (text search), category_id (exact match), min_price and max_price (range), and in_stock_only (boolean flag). Sort results by relevance (full-text score), created_at (newest), or price (lowest/highest). Return only products from sellers with status 'approved' and exclude any products with 'isDeleted' flag set to true. Limit results to 10-50 items per page based on request parameter. Calculate price range for each product by selecting min and max variant prices. Aggregate average rating and review count from all non-deleted reviews. Return result as paginated list with total count for frontend pagination. Cache search results for 5 minutes using a composite key based on all search parameters to improve performance.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async search(
    @TypedBody()
    body: IShoppingMallProduct.IRequest,
  ): Promise<IPageIShoppingMallProduct.ISummary> {
    try {
      return await postShoppingMallSearchProductsGlobal({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
