import { Controller } from "@nestjs/common";
import { TypedRoute, TypedParam, TypedBody } from "@nestia/core";
import typia, { tags } from "typia";
import { postShoppingMallAdminAdminsSellersSellerIdApprove } from "../../../../../providers/postShoppingMallAdminAdminsSellersSellerIdApprove";
import { AdminAuth } from "../../../../../decorators/AdminAuth";
import { AdminPayload } from "../../../../../decorators/payload/AdminPayload";
import { postShoppingMallAdminAdminsSellersSellerIdReject } from "../../../../../providers/postShoppingMallAdminAdminsSellersSellerIdReject";
import { postShoppingMallAdminAdminsSellersSellerIdSuspend } from "../../../../../providers/postShoppingMallAdminAdminsSellersSellerIdSuspend";
import { postShoppingMallAdminAdminsSellersSellerIdBan } from "../../../../../providers/postShoppingMallAdminAdminsSellersSellerIdBan";
import { postShoppingMallAdminAdminsSellersSellerIdUnban } from "../../../../../providers/postShoppingMallAdminAdminsSellersSellerIdUnban";

import { IShoppingMallSeller } from "../../../../../api/structures/IShoppingMallSeller";
import { IShoppingMallDeliveryConfirmation } from "../../../../../api/structures/IShoppingMallDeliveryConfirmation";
import { IShoppingMallAdministrativeRejectionReason } from "../../../../../api/structures/IShoppingMallAdministrativeRejectionReason";

@Controller("/shoppingMall/admin/admins/sellers/:sellerId")
export class ShoppingmallAdminAdminsSellersController {
  /**
   * Approve a seller's registration application.
   *
   * This operation allows administrators or super administrators to approve a
   * seller's registration request, changing their status from 'pending' to
   * 'approved'. The approvalStatus field in the shopping_mall_sellers table is
   * updated from 'pending' to 'approved'. Valid values for approvalStatus are
   * 'pending', 'approved', and 'rejected'.
   *
   * Security: Only users with admin or super-admin roles can perform this
   * operation. The seller's approval status must be 'pending' for this
   * operation to succeed. This action is recorded in the system's audit trail
   * through the associated admin session.
   *
   * Related Operations: When a seller is rejected instead of approved, use the
   * /admins/sellers/{sellerId}/reject endpoint. The status change from pending
   * to approved triggers automatic notifications to the seller.
   *
   * Data Integrity: This operation preserves the seller's history - even if
   * their account is later suspended or deleted, the approval timestamp remains
   * in the audit trail. This ensures compliance with marketplace governance
   * requirements.
   *
   * @param connection
   * @param sellerId Unique identifier of the seller whose registration is being
   *   approved
   * @param body Update details for seller approval status change
   * @x-autobe-specification Update the approvalStatus field of the shopping_mall_sellers table from 'pending' to 'approved' using the sellerId as the primary key. Create a shopping_mall_seller_approval_snapshot entry recording the approval action, including the admin_id who approved, the reason provided, and the timestamp. Validate that the requesting user has admin or super-admin role. Validate that the seller's status is currently 'pending'. Send a notification to the seller's email address confirming approval. Use the shopping_mall_admins table to verify the requester's permissions. All actions occur in a transaction to ensure data consistency.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("approve")
  public async approve(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("sellerId")
    sellerId: string,
    @TypedBody()
    body: IShoppingMallSeller.IUpdate,
  ): Promise<IShoppingMallSeller> {
    try {
      return await postShoppingMallAdminAdminsSellersSellerIdApprove({
        admin,
        sellerId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Reject a pending seller application.
   *
   * This operation allows a platform administrator to reject a seller's
   * application for registration. When an application is submitted, the
   * seller's status is set to 'pending_approval'. This endpoint enables
   * administrators to deny these applications with a specific reason.
   *
   * Security: This operation requires admin or super admin authentication. The
   * sellerId in the path must correspond to an active seller application with
   * status 'pending_approval'. Only users with administrator permissions can
   * call this endpoint.
   *
   * Business Logic: The rejection reason must be a non-empty string with a
   * minimum length of 10 characters as specified in the requirements. Once
   * rejected, the seller's account cannot be used for registration until they
   * submit a new application. The seller is notified via email with the
   * rejection reason. Rejected sellers are not permitted to create new
   * applications for 30 days as per business policy.
   *
   * Relationship to other operations: This operation is complementary to
   * /admins/sellers/{sellerId}/approve, which accepts seller applications. The
   * rejection action prevents sellers from continuing a pending registration
   * process. Only actions on pending applications are permitted; applications
   * already approved or rejected cannot be processed by this endpoint.
   *
   * No additional request body is required beyond the rejection reason.
   *
   * @param connection
   * @param sellerId Unique identifier of the seller application to reject
   *   (global scope).
   * @param body Rejection reason providing justification for denying the seller
   *   application. This reason must be provided and must be at least 10
   *   characters long.
   * @x-autobe-specification This operation handles the rejection of a seller application. When called, it retrieves the seller application associated with the sellerId from the shopping_mall_sellers table. It verifies the seller's current status is 'pending_approval'. It then updates the seller's status to 'rejected' and records the rejection reason provided in the request body. The operation logs the action and notifies the seller via email. Strict validation ensures the rejection reason is provided and meets minimum length requirements (10 characters). This operation is restricted to admin role users only.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("reject")
  public async reject(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("sellerId")
    sellerId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IShoppingMallAdministrativeRejectionReason,
  ): Promise<IShoppingMallDeliveryConfirmation> {
    try {
      return await postShoppingMallAdminAdminsSellersSellerIdReject({
        admin,
        sellerId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Suspend a seller account as part of administrative oversight. This
   * operation permanently restricts the seller's access to the platform and
   * disables their ability to manage products, view orders, or interact with
   * customers until explicitly unsuspended by an administrator. The suspension
   * action is triggered by an admin user who provides the sellerId as a path
   * parameter to identify the target seller account.
   *
   * All seller data including product listings, order history, and customer
   * interactions are preserved in the system, but the seller account becomes
   * inactive. Customers can still view existing seller shop information, but
   * cannot make new purchases from the suspended seller. The suspension is
   * recorded in the system audit trail with the acting administrator's identity
   * and timestamp.
   *
   * This operation is part of the platform's governance framework and can be
   * used to enforce compliance, address policy violations, or handle security
   * incidents. Suspended sellers cannot apply for reinstatement through
   * self-service; their account status must be reviewed and acted upon by
   * administrators.
   *
   * Related operations: POST /admins/sellers/{sellerId}/unsuspend (to restore
   * account access), POST /admins/sellers/{sellerId}/reject (to permanently
   * decline registration), and POST /admins/sellers/{sellerId}/ban (to
   * permanently ban account with legal consequences).
   *
   * @param connection
   * @param sellerId Unique identifier of the target seller account to be
   *   suspended (global scope)
   * @x-autobe-specification Update the shopping_mall_sellers table to set isSuspended = true for the specified sellerId. Add a system-generated audit log entry recording the suspension action with timestamp, acting admin ID, and reason (default: 'Admin-initiated suspension'). Validate that sellerId references an existing seller record. Ensure suspension does not affect pending orders or refund requests. Set updatedAt timestamp to current time. No database transactions needed as this is a single record update.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("suspend")
  public async suspend(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("sellerId")
    sellerId: string & tags.Format<"uuid">,
  ): Promise<IShoppingMallSeller> {
    try {
      return await postShoppingMallAdminAdminsSellersSellerIdSuspend({
        admin,
        sellerId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Permanently ban a seller account from the shopping mall platform. This
   * operation immediately revokes all seller privileges, hides the seller's
   * shop from all customer views, removes the seller's products from search
   * results, and prevents any further authentication. This ban is irreversible
   * and is intended for sellers who violate platform policies. The seller's
   * existing orders and customer interactions remain accessible for audit
   * purposes but no new transactions can be initiated by the seller. No
   * customer-facing notification is sent automatically; it is the
   * administrator's responsibility to communicate this action to the seller via
   * external channels.
   *
   * This operation interacts with the shopping_mall_sellers table in the
   * database, updating the seller's status to 'banned' and clearing any active
   * session tokens associated with this seller. The seller's profile and shop
   * metadata are preserved for record-keeping but rendered inactive on the
   * platform.
   *
   * This operation should only be invoked by users with super admin privileges.
   * The system logs this action for audit purposes, including the admin who
   * performed the ban, timestamp, and the sellerId affected.
   *
   * Related operations: POST /admin/sellers/{sellerId}/unban (to unban a
   * seller), GET /sellers/manage (to list all sellers with their statuses).
   *
   * @param connection
   * @param sellerId Unique identifier of the seller to be banned. Must be a
   *   valid UUID string as stored in the shopping_mall_sellers table.
   * @x-autobe-specification Update the shopping_mall_sellers table by setting isBanned = true for the specified sellerId. Query the shopping_mall_seller_sessions table and delete all active sessions associated with this sellerId. Update the seller's account status in the database to 'banned'. Log this action in the audit_log table with action 'SELLER_BANNED', actor (admin) ID, sellerId, and timestamp. Ensure the sellerId param is validated as a valid UUID before execution. Return 204 No Content on success. If sellerId is not found in shopping_mall_sellers table, return 404 Not Found. If the seller is already banned, return 204 No Content (idempotent). This operation does not delete any data — it only marks the seller as banned and invalidates sessions.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("ban")
  public async ban(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("sellerId")
    sellerId: string,
  ): Promise<void> {
    try {
      return await postShoppingMallAdminAdminsSellersSellerIdBan({
        admin,
        sellerId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Administers the unban action for a seller account whose isBanned flag is
   * set to true.
   *
   * This operation allows authorized administrators to reinstate access for a
   * seller account that has been restricted from platform activities. The
   * seller's account must be currently in a 'banned' state, as determined by
   * the isBanned boolean flag in the shopping_mall_sellers database table. Upon
   * successful execution, the system removes the restriction by setting
   * isBanned to false, restoring the seller's ability to list products, manage
   * inventory, process orders, and interact with customers on the platform.
   *
   * Security considerations require that only users with admin or super-admin
   * privileges can invoke this operation. The operation does not require a
   * request body since the action is fully determined by the endpoint path and
   * HTTP method. The seller identifier is provided exclusively via the
   * {sellerId} path parameter.
   *
   * This unban action does not affect the seller's account creation date,
   * historical data, previous approval status, or any other attributes. It only
   * changes the isBanned flag from true to false. Related administrative
   * operations include ban (POST /admins/sellers/{sellerId}/ban) and suspend
   * (POST /admins/sellers/{sellerId}/suspend).
   *
   * @param connection
   * @param sellerId Unique identifier of the seller account to be unbanned.
   * @x-autobe-specification Perform administrative unban operation on a seller account. Verify the requesting user has admin privileges. Locate seller by provided sellerId path parameter. Confirm seller.isBanned is true before performing unban. Set seller.isBanned to false. Log unban action in audit trail. Return 204 No Content on success. Return 403 Forbidden if requester lacks admin rights. Return 404 Not Found if sellerId does not exist. Return 400 Bad Request if seller is not currently banned.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("unban")
  public async unban(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("sellerId")
    sellerId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await postShoppingMallAdminAdminsSellersSellerIdUnban({
        admin,
        sellerId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

import { Controller } from "@nestjs/common";
import { TypedRoute, TypedParam } from "@nestia/core";
import typia from "typia";
import { postShoppingMallAdminAdminsSellersSellerIdUnsuspend } from "../../../../../../providers/postShoppingMallAdminAdminsSellersSellerIdUnsuspend";
import { AdminAuth } from "../../../../../../decorators/AdminAuth";
import { AdminPayload } from "../../../../../../decorators/payload/AdminPayload";

import { IShoppingMallSeller } from "../../../../../../api/structures/IShoppingMallSeller";

@Controller("/shoppingMall/admin/admins/sellers/:sellerId/unsuspend")
export class ShoppingmallAdminAdminsSellersUnsuspendController {
  /**
   * Restore a suspended seller's account to active status for platform
   * operation.
   *
   * This operation is restricted to administrators with appropriate privileges
   * and is used to reverse a previous suspension action. When executed, the
   * system will change the seller's account status from 'suspended' to
   * 'active', thereby restoring their ability to log in, manage products, and
   * receive order notifications. This action is irreversible without
   * administrative oversight and must be logged for audit compliance.
   *
   * The seller's shop visibility is immediately restored across all platform
   * interfaces, including product listings and search results. No
   * customer-facing notifications are automatically sent, but administrators
   * may choose to communicate the reinstatement directly. The system generates
   * a snapshot preserving the seller's state prior to unsuspension per the
   * snapshot principle documentation.
   *
   * Security: Only administrators with elevated privileges can perform this
   * action. The sellerId must belong to a currently suspended seller account.
   * If the seller is not suspended or the sellerId does not exist, the system
   * will return a 404 error.
   *
   * This operation has no effect on order history, previous cancellations, or
   * outstanding refund requests. It only modifies the seller's access
   * permissions within the system. Related operations: POST
   * /admins/sellers/{sellerId}/suspend (to suspend) and GET /sellers/manage (to
   * view suspension status).
   *
   * @param connection
   * @param sellerId Unique identifier of the seller account to be unsuspended.
   * @x-autobe-specification Update the seller record in shopping_mall_sellers table setting is_suspended to false and update_at timestamp. Create a seller profile snapshot capturing the seller's status before update (is_suspended: true to false). Log administrative action with admin ID and timestamp.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async update(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("sellerId")
    sellerId: string,
  ): Promise<IShoppingMallSeller> {
    try {
      return await postShoppingMallAdminAdminsSellersSellerIdUnsuspend({
        admin,
        sellerId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

import { Controller } from "@nestjs/common";
import { TypedRoute, TypedParam } from "@nestia/core";
import typia from "typia";
import { postShoppingMallAdminAdminsCustomersCustomerIdBan } from "../../../../../../providers/postShoppingMallAdminAdminsCustomersCustomerIdBan";
import { AdminAuth } from "../../../../../../decorators/AdminAuth";
import { AdminPayload } from "../../../../../../decorators/payload/AdminPayload";

@Controller("/shoppingMall/admin/admins/customers/:customerId/ban")
export class ShoppingmallAdminAdminsCustomersBanController {
  /**
   * Permanently ban a customer account from the Shopping Mall platform,
   * preventing all future access and interactions.
   *
   * This operation is exclusively available to administrators and
   * super-administrators. When executed, the system immediately sets the
   * isBanned field to true for the specified customer account, which prevents
   * any further authentication, cart activity, order placement, profile
   * updates, or any other system interaction. The banned status is persistent
   * and visible to all system components, including the authentication service,
   * customer dashboard, and admin management interfaces.
   *
   * This action is irreversible via API. Legal compliance requires preservation
   * of customer data even after ban, so the customer record remains in the
   * database with all order history, reviews, and preferences intact, but
   * entirely locked out. Any attempts to access the platform with the
   * customer's credentials will be blocked at the authentication layer. The ban
   * action also triggers system notifications to relevant parties, such as
   * canceled pending order items or suspended seller customer interactions,
   * although these are performed internally by the system without separate API
   * endpoints.
   *
   * This operation does not require a request body because the enforcement of
   * the ban is based entirely on the customerId path parameter and the
   * privilege level of the authenticated administrator. The backend service
   * validates that the caller has sufficient administrative privileges before
   * applying the ban. The ban action affects all customer data uniformly
   * regardless of specific customer characteristics.
   *
   * Related operations: GET /admin/customers/manage to list all customers and
   * their ban status; POST /admin/customers/{customerId}/unban to reverse a
   * ban.
   *
   * @param connection
   * @param customerId The unique identifier of the customer to be banned.
   * @x-autobe-specification Update the shopping_mall_customers table by setting isBanned = true where customerId = path parameter. Verify that the authenticated user has either 'admin' or 'superAdmin' role. Log the ban action in the audit log with actor ID and timestamp. Return 204 No Content on success. Return 404 if customer does not exist. Return 403 if caller lacks sufficient privileges.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async erase(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("customerId")
    customerId: string,
  ): Promise<void> {
    try {
      return await postShoppingMallAdminAdminsCustomersCustomerIdBan({
        admin,
        customerId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

