@Controller(
  "/shoppingMall/admin/admins/orders/:orderId/items/:orderItemId/refund",
)
export class ShoppingmallAdminAdminsOrdersItemsController {
  /**
   * Force a refund for a specific order item through administrative override.
   *
   * This is an administrative endpoint available exclusively to super
   * administrators for handling exceptional cases requiring immediate financial
   * remediation. It allows overriding the standard customer-initiated refund
   * process when policy violations, system errors, or critical customer service
   * issues demand immediate action.
   *
   * The operation must be used with extreme caution, as it bypasses customer
   * confirmation and standard refund approval workflows. This endpoint is
   * reserved for situations where the platform needs to initiate a refund
   * directly, such as when an order has been processed in error, a system
   * glitch has resulted in improper charge, or a customer is facing severe
   * hardship due to platform issues.
   *
   * Security: Only authenticated super administrators (not regular admins) can
   * use this endpoint. The request is verified against the platform's access
   * control system to ensure privilege escalation is properly authorized.
   *
   * Implementation note: This operation creates a refund request with the
   * reason 'admin-forced', triggers inventory restoration for the refunded
   * item, and initiates the payment gateway refund process. The order status is
   * updated to 'partially_refunded' if the refund affects only one item among
   * multiple, or 'fully_refunded' if it affects the entire order.
   *
   * Related operations: Customer-initiated refunds are handled through POST
   * /orders/{orderId}/items/{orderItemId}/refund.
   *
   * @param connection
   * @param orderId Unique identifier of the order containing the item to be
   *   refunded. Uses UUID format.
   * @param orderItemId Unique identifier of the specific order item within the
   *   order to be refunded. Uses UUID format.
   * @x-autobe-specification When this endpoint is called, the system must create a refund request record in the shopping_mall_refund_requests table with status 'admin-initiated'. The system must validate that the requesting user is a super admin, extract the order and order item details from the shopping_mall_orders and shopping_mall_order_items tables, and ensure the order item has been delivered. The refund request must capture the refund reason as 'admin-forced', the requester's admin ID, and timestamp. The system must then trigger inventory restoration for the refunded item and initiate a payment gateway refund process. This operation should audit all changes and update order status to 'partially_refunded' or 'fully_refunded' based on the item being refunded. No user notification is sent automatically - this is an administrative action.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async refund(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("orderId")
    orderId: string & tags.Format<"uuid">,
    @TypedParam("orderItemId")
    orderItemId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await postShoppingMallAdminAdminsOrdersOrderIdItemsOrderItemIdRefund(
        {
          admin,
          orderId,
