@Controller("/shoppingMall/admin/admins/products/:productId")
export class ShoppingmallAdminAdminsProductsController {
  /**
   * Permanently delete a product from the shopping mall platform.
   *
   * This administrative operation permanently removes a product record from the
   * system database. The product is completely deleted, and all associated data
   * including images, variants, and inventory records are also removed. This is
   * a hard delete operation with no possibility of recovery.
   *
   * Security and Access Control: This operation is restricted to
   * super-administrators with elevated privileges. Regular administrators are
   * not permitted to invoke this endpoint. The system enforces strict
   * authentication and authorization checks that validate the caller's role and
   * admin type (super-admin) before executing deletion.
   *
   * Data Integrity Impact: This operation has cascading effects. All product
   * images, variants (SKUs), inventory records, and any associated product
   * snapshots are permanently removed from the database. This deletion is
   * irreversible. Any orders containing this product remain in the database for
   * audit purposes, but the product reference in those orders becomes
   * orphaned.
   *
   * Related Operations: This operation cannot be replaced by soft-deletion
   * workflows (e.g., update from isDeleted=false to isDeleted=true), as the
   * system does not utilize soft-delete columns in the products table. Any
   * attempts to restore a deleted product must be handled through external data
   * recovery or re-creation processes.
   *
   * Admin Oversight: The deletion event for this product is logged in the
   * system audit trail, including the admin ID who performed the deletion and
   * the timestamp of the operation.
   *
   * Note: This endpoint is not intended for regularly used product removals
   * (e.g., discontinued items). For such cases, use the status flag or approve
   * seller-initiated hard deletions, which are documented in other workflows.
   *
   * @param connection
   * @param productId Unique identifier of the product to be deleted.
   * @x-autobe-specification Validate that caller has super-admin privileges. Retrieve product record by productId UUID from the shopping_mall_products table. If product does not exist, return 404 Not Found. If product exists, perform cascading deletion of all related records: remove entries from shopping_mall_product_images, shopping_mall_product_variants, shopping_mall_inventory_records, and shopping_mall_product_snapshots associated with this product ID. Log the deletion event in the system audit trail with caller information and timestamp. Remove the product record from shopping_mall_products table. Return 204 No Content on successful deletion.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete()
  public async erase(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("productId")
    productId: string,
  ): Promise<void> {
